<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import type { CharacterCard, CharacterSummary, YsmOptions } from '@shared/characterCard'
import { numenApi } from '../numenApi'
import { errText } from '../api'
import { toast } from '../store'
import ConfirmModal from './ConfirmModal.vue'
import YsmViewer3D from './YsmViewer3D.vue'
import { ysmApi } from '../ysmApi'
import type { InstanceTarget } from '@shared/instanceCenter'
import type { YsmAsset } from '@shared/ysm'
import SkinViewer3D from './SkinViewer3D.vue'
const props=defineProps<{currentId?:string;canApply:boolean;running:boolean;connected?:boolean;companionId?:string;companionName?:string;instanceTarget?:InstanceTarget}>()
const emit=defineEmits<{changed:[];apply:[id:string]}>()
const cards=ref<CharacterSummary[]>([]),query=ref(''),draft=ref<CharacterCard>(),baseline=ref(''),busy=ref(''),error=ref(''),deleteOpen=ref(false),discardOpen=ref(false)
const page=ref(1),panel=ref<'persona'|'ysm'>('persona'),ysm=ref<YsmOptions>(),ysmMessage=ref('')
const localYsm=ref<YsmAsset[]>([])
const pageSize=8
let pending:(()=>Promise<void>)|undefined,disposed=false
const dirty=computed(()=>!!draft.value&&JSON.stringify(draft.value)!==baseline.value)
const filtered=computed(()=>cards.value.filter(card=>[card.name,card.excerpt].join(' ').toLowerCase().includes(query.value.toLowerCase())))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize)))
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize))
const ysmTextures=computed(()=>[...new Set([...(localYsm.value.find(a=>a.id===draft.value?.appearance?.ysm?.assetId)?.textures??[]),...(draft.value?.appearance?.ysm?.model===ysm.value?.currentModel?ysm.value?.textures??[]:[])])])
const locked=computed(()=>props.running&&draft.value?.id===props.currentId)
const canYsm=computed(()=>props.connected&&!!props.companionId&&!props.running&&!busy.value)
watch(query,()=>page.value=1)
watch(pages,value=>page.value=Math.min(page.value,value))
watch(()=>props.companionId,()=>{ysm.value=undefined;ysmMessage.value=''})
async function act(name:string,fn:()=>Promise<void>){if(busy.value)return;busy.value=name;error.value='';try{await fn()}catch(e){if(!disposed)error.value=errText(e)}finally{if(!disposed)busy.value=''}}
async function reload(){const list=await numenApi.cards();if(disposed)return;cards.value=list;emit('changed')}
function clearDraft(){sessionStorage.removeItem('nomadcraft.characterDraft')}
function accept(card:CharacterCard){if(disposed)return;clearDraft();draft.value=card;baseline.value=JSON.stringify(card);panel.value='persona';ysmMessage.value=''}
async function guard(fn:()=>Promise<void>){if(dirty.value){pending=fn;discardOpen.value=true}else await fn()}
async function discard(){clearDraft();discardOpen.value=false;const fn=pending;pending=undefined;await fn?.()}
function back(){void guard(async()=>{draft.value=undefined;baseline.value='';clearDraft();error.value=''})}
function newCard(){accept({id:'',name:'新角色',text:'',createdAt:Date.now(),updatedAt:Date.now()});baseline.value=''}
function template(){accept({id:'',name:'小诺',text:"# 身份\n你是小诺，一位住在 Minecraft 世界里的旅伴。你喜欢和玩家一起探索、建造温暖的家。\n\n# 性格与相处方式\n温柔、活泼，偶尔有点俏皮。对朋友真诚，遇到困难一起想办法；失败时坦诚，不把计划当成完成的事情。\n\n# 说话风格\n用简短自然的中文聊天，像站在玩家身旁的朋友。",createdAt:Date.now(),updatedAt:Date.now()});baseline.value=''}
async function choose(id:string){await act('load',async()=>accept(await numenApi.cardGet(id)))}
async function save(){if(!draft.value)return;await act('save',async()=>{const value=draft.value!;const card=await numenApi.cardSave({id:value.id||undefined,name:value.name,text:value.text,avatar:value.avatar??'',appearance:value.appearance??null});if(disposed)return;const currentPanel=panel.value;accept(card);panel.value=currentPanel;await reload();toast('角色卡已保存','success')})}
async function importCard(){await act('import',async()=>{const card=await numenApi.cardImport();if(card&&!disposed){accept(card);await reload();toast('角色卡已导入','success')}})}
async function duplicate(){if(!draft.value?.id)return;await guard(()=>act('copy',async()=>{accept(await numenApi.cardDuplicate(draft.value!.id));await reload()}))}
async function remove(){if(!draft.value?.id)return;await act('delete',async()=>{cards.value=await numenApi.cardDelete(draft.value!.id);if(disposed)return;draft.value=undefined;baseline.value='';clearDraft();deleteOpen.value=false;emit('changed')})}
async function avatar(){await act('avatar',async()=>{const image=await numenApi.cardAvatar();if(image&&draft.value&&!disposed)draft.value.avatar=image})}
async function skin(){await act('skin',async()=>{const image=await numenApi.cardSkin();if(image&&draft.value&&!disposed){draft.value.appearance??={};draft.value.appearance.skin={png:image,variant:draft.value.appearance.skin?.variant??'classic'}}})}
function clearSkin(){if(draft.value?.appearance)delete draft.value.appearance.skin}
function toggleYsm(event:Event){if(!draft.value)return;draft.value.appearance??={};if((event.target as HTMLInputElement).checked)draft.value.appearance.ysm={model:''};else delete draft.value.appearance.ysm;ysmMessage.value=''}
async function importYsm(){await act('ysmImport',async()=>{const asset=await ysmApi.import();if(!asset||!draft.value||disposed)return;localYsm.value=await ysmApi.list();draft.value.appearance??={};draft.value.appearance.ysm={model:asset.modelId,texture:asset.textures[0],assetId:asset.id};panel.value='ysm'})}
function selectYsmAsset(event:Event){const id=(event.target as HTMLSelectElement).value;if(!draft.value?.appearance?.ysm)return;const asset=localYsm.value.find(a=>a.id===id);if(asset)draft.value.appearance.ysm={model:asset.modelId,texture:asset.textures[0],assetId:asset.id};else delete draft.value.appearance.ysm.assetId}
async function exportCard(format:'md'|'json'){if(!draft.value?.id)return;await act('export',async()=>{const file=await numenApi.cardExport(draft.value!.id,format);if(file)toast('角色卡已导出','success')})}
async function exportSkin(){if(!draft.value?.id)return;await act('exportSkin',async()=>{if(await numenApi.cardSkinExport(draft.value!.id))toast('皮肤已导出，可在游戏内 Numen 皮肤面板导入','success')})}
async function loadYsm(){const companion=props.companionId;if(!companion)return;await act('ysmQuery',async()=>{ysmMessage.value='';const result=await numenApi.ysmOptions(companion);if(!disposed&&companion===props.companionId){ysm.value=result;ysmMessage.value='已读取 '+(props.companionName||'当前同伴')+' 的模型清单'}})}
async function prepareYsm(){const id=draft.value?.appearance?.ysm?.assetId;if(!id||!props.instanceTarget)return;await act('ysmPrepare',async()=>{const result=await ysmApi.install(props.instanceTarget!,id);ysmMessage.value=result.count?'已从独立模型库准备模型资源：'+result.modelId:'实例已包含相同模型资源：'+result.modelId;toast(ysmMessage.value,'success')})}
async function applyYsm(){const id=draft.value?.id,companion=props.companionId;if(!id||!companion||dirty.value)return;await act('ysmApply',async()=>{ysmMessage.value='';const result=await numenApi.cardYsmApply(id,companion);if(!disposed&&companion===props.companionId){ysm.value=result;ysmMessage.value='游戏已确认：'+result.currentModel+(result.currentTexture?' · '+result.currentTexture:'');toast('YSM 外观已在游戏中生效','success')}})}
function useCurrentYsm(){if(!draft.value||!ysm.value?.currentModel)return;draft.value.appearance??={};draft.value.appearance.ysm={model:ysm.value.currentModel,texture:ysm.value.currentTexture}}
onMounted(()=>{void act('load',async()=>{localYsm.value=await ysmApi.list();await reload();if(disposed)return;const cached=sessionStorage.getItem('nomadcraft.characterDraft');if(cached){try{const value=JSON.parse(cached);if(typeof value.draft?.name==='string'&&typeof value.draft?.text==='string'){draft.value=value.draft;baseline.value=value.baseline??'';toast('已恢复未保存的角色草稿','info');return}clearDraft()}catch{clearDraft()}}})})
onUnmounted(()=>{disposed=true;if(dirty.value&&draft.value){try{sessionStorage.setItem('nomadcraft.characterDraft',JSON.stringify({draft:draft.value,baseline:baseline.value}))}catch{toast('角色草稿过大，未能暂存；请在离开编辑器前保存','error')}}})
</script>
<template>
  <section class="character-library">
    <header class="library-toolbar">
      <div class="library-title"><button v-if="draft" class="back-button" :disabled="!!busy" aria-label="返回角色库" @click="back">←</button><div><h2>{{draft?'角色设置':'角色卡库'}} <small v-if="!draft">{{cards.length}}</small><small v-else-if="dirty" class="unsaved">未保存</small></h2><p>{{draft?'给这位同伴定义人设与外观。':'挑一位旅伴，开始下一段冒险。'}}</p></div></div>
      <div v-if="!draft" class="library-actions"><button class="btn btn-ghost" :disabled="!!busy" @click="importCard">导入角色卡</button><button class="btn btn-ghost" :disabled="!!busy" @click="template">示例角色</button><button class="btn btn-primary" :disabled="!!busy" @click="newCard">＋ 新建角色</button></div>
      <button v-else class="btn btn-primary" :disabled="!!busy||locked" @click="save">{{busy==='save'?'正在保存…':'保存角色卡'}}</button>
    </header>
    <p v-if="error" class="role-error" role="alert">{{error}}</p>
    <template v-if="!draft">
      <div class="gallery-tools"><input v-model="query" aria-label="搜索角色" placeholder="搜索角色名称或人设…"><span>点击卡片，编辑角色</span></div>
      <div v-if="visible.length" class="character-grid">
        <article v-for="card in visible" :key="card.id" class="character-tile" :class="{bound:card.id===currentId}">
          <button class="tile-open" :disabled="!!busy" :aria-label="'编辑角色 '+card.name" @click="choose(card.id)">
            <div class="tile-preview"><YsmViewer3D v-if="card.appearance?.ysm?.assetId" :asset-id="card.appearance.ysm.assetId" :texture="card.appearance.ysm.texture" :compact="true"/><SkinViewer3D v-else :src="card.appearance?.skin?.png" :variant="card.appearance?.skin?.variant" :auto-detect-variant="false" animation="walk"/><span v-if="card.id===currentId" class="tile-badge current">当前人设</span><span v-else-if="card.appearance?.ysm" class="tile-badge">YSM</span><small>{{card.appearance?.ysm?.assetId?'YSM 立体预览':card.appearance?.ysm?'未关联本地模型 · 普通皮肤示意':card.appearance?.skin?'立体皮肤':'默认皮肤'}}</small></div>
            <div class="tile-caption"><img v-if="card.avatar" :src="card.avatar" alt=""><div><h3>{{card.name}}</h3><p>{{card.appearance?.ysm?card.appearance.ysm.model:card.appearance?.skin?.variant==='slim'?'纤细手臂 · Minecraft':'标准手臂 · Minecraft'}}</p></div><span aria-hidden="true">↗</span></div>
          </button>
        </article>
      </div>
      <div v-else class="library-empty"><span>✦</span><h3>{{query?'没有找到这位旅伴':'你的旅伴，从这里开始'}}</h3><p>{{query?'换个关键词试试。':'创建角色，写下人设，再为同伴挑一套皮肤。'}}</p><button v-if="!query" class="btn btn-primary" :disabled="!!busy" @click="newCard">创建第一位角色</button></div>
      <footer class="gallery-footer"><span>JSON 包含人设与外观；Markdown 只包含人设正文。</span><div v-if="pages>1" class="pagination"><button class="btn btn-ghost" :disabled="page===1" @click="page--">上一页</button><span>{{page}} / {{pages}}</span><button class="btn btn-ghost" :disabled="page===pages" @click="page++">下一页</button></div></footer>
    </template>
    <div v-else class="character-editor">
      <div class="editor-content">
        <aside class="appearance-panel"><div class="detail-preview"><YsmViewer3D v-if="draft.appearance?.ysm?.assetId" :asset-id="draft.appearance.ysm.assetId" :texture="draft.appearance.ysm.texture"/><SkinViewer3D v-else :src="draft.appearance?.skin?.png" :variant="draft.appearance?.skin?.variant" :auto-detect-variant="false" animation="walk"/><span class="preview-label">{{draft.appearance?.ysm?.assetId?'YSM 模型预览':'标准皮肤预览'}}</span><small v-if="!draft.appearance?.ysm?.assetId">行走动画 · 拖动旋转 · 滚轮缩放</small></div>
          <div v-if="!draft.appearance?.ysm?.assetId" class="skin-settings"><div class="skin-actions"><button class="btn btn-ghost" :disabled="!!busy||locked" @click="skin">导入皮肤</button><button class="text-btn" :disabled="!!busy||locked||!draft.appearance?.skin" @click="clearSkin">恢复默认</button></div><label v-if="draft.appearance?.skin" class="variant-label">手臂模型<select v-model="draft.appearance.skin.variant" :disabled="!!busy||locked"><option value="classic">标准 · Steve</option><option value="slim">纤细 · Alex</option></select></label><p class="skin-note">支持 64 × 64 / 64 × 32 PNG。此处保存并预览皮肤；游戏内使用需导出 PNG，再在 Numen 皮肤面板导入并完成签名。</p><button v-if="draft.appearance?.skin" class="text-btn" :disabled="!!busy||dirty||!draft.id" @click="exportSkin">导出皮肤 PNG ↗</button></div>
        </aside>
        <div class="persona-panel"><div class="editor-identity"><button class="avatar-button" :disabled="!!busy||locked" aria-label="更换角色头像" @click="avatar"><img v-if="draft.avatar" :src="draft.avatar" alt="角色头像"><span v-else>{{draft.name.slice(0,1)||'✦'}}</span><small>头像</small></button><label class="name-label" for="character-name">角色名称<input id="character-name" v-model="draft.name" maxlength="120" :disabled="!!busy||locked" placeholder="给旅伴起个名字"></label></div>
          <nav class="detail-tabs" aria-label="角色设置"><button :class="{active:panel==='persona'}" @click="panel='persona'">人设正文</button><button :class="{active:panel==='ysm'}" @click="panel='ysm'">YSM 外观 <small v-if="draft.appearance?.ysm">已设置</small></button></nav>
          <div v-if="panel==='persona'" class="persona-editor"><label for="character-persona">自由人设 <small>{{draft.text.length.toLocaleString()}} / 100,000</small></label><textarea id="character-persona" v-model="draft.text" maxlength="100000" :disabled="!!busy||locked" placeholder="# 身份&#10;你是谁？&#10;&#10;写下角色背景、说话风格、相处方式，或你想让同伴遵守的约定。"></textarea><p>支持 Markdown，正文会原样作为角色提示词。留空时使用 AI 接入中的全局人设。</p></div>
          <div v-else class="ysm-editor"><div class="ysm-intro"><b>Yes Steve Model</b><span>立体模型与动作</span></div><p class="muted">关联本地模型即可预览立体外观和自带动作；连接游戏后，可将配置应用到所选 AI 同伴。</p><label class="ysm-toggle"><input type="checkbox" :checked="!!draft.appearance?.ysm" :disabled="!!busy||locked" @change="toggleYsm">为此角色保存 YSM 外观</label>
            <template v-if="draft.appearance?.ysm"><div class="local-ysm-pick"><label class="field-label">独立模型库<select aria-label="角色卡 YSM 独立模型" :value="draft.appearance.ysm.assetId||''" :disabled="!!busy||locked" @change="selectYsmAsset"><option value="">仅使用游戏已有模型</option><option v-for="asset in localYsm" :key="asset.id" :value="asset.id">{{asset.name}} · {{asset.animationCount}} 个动作</option></select></label><button class="btn btn-ghost" :disabled="!!busy||locked" @click="importYsm">{{busy==='ysmImport'?'正在解析…':'导入 YSM 模型…'}}</button></div><label class="field-label" for="character-ysm-model">模型 ID<input id="character-ysm-model" v-model="draft.appearance.ysm.model" list="character-ysm-models" maxlength="512" :disabled="!!busy||locked" placeholder="例如 misc/1_alex 或模型文件名.ysm"></label><datalist id="character-ysm-models"><option v-for="model in ysm?.models??[]" :key="model" :value="model"/></datalist><label class="field-label" for="character-ysm-texture">贴图 ID <small>可选 · 留空使用模型默认贴图</small><input id="character-ysm-texture" v-model="draft.appearance.ysm.texture" list="character-ysm-textures" maxlength="256" :disabled="!!busy||locked" placeholder="选择本地模型贴图，或读取游戏里的贴图清单"></label><datalist id="character-ysm-textures"><option v-for="texture in ysmTextures" :key="texture" :value="texture"/></datalist></template>
            <p v-if="draft.appearance?.ysm?.assetId" class="muted">模型原文件独立保存，切换或删除游戏实例不会删除它。绑定角色或开始陪玩时，会自动检查并补齐当前实例的模型资源。</p><p v-else-if="draft.appearance?.ysm" class="muted">当前只记录游戏模型 ID。要随角色迁入新实例，请从独立模型库关联模型文件。</p><div class="ysm-live"><div class="ysm-target">游戏同伴 <strong>{{connected?(companionName||'尚未选择'):'未连接游戏'}}</strong></div><p v-if="ysm?.currentModel" class="ysm-current">当前：{{ysm.currentModel}} <span v-if="ysm.currentTexture">· {{ysm.currentTexture}}</span></p><div class="ysm-actions"><button v-if="draft.appearance?.ysm?.assetId" class="btn btn-ghost" :disabled="!!busy||!instanceTarget||running" @click="prepareYsm">{{busy==='ysmPrepare'?'正在准备…':'准备模型到当前实例'}}</button><button class="btn btn-ghost" :disabled="!canYsm" @click="loadYsm">{{busy==='ysmQuery'?'正在读取…':'读取游戏模型'}}</button><button class="text-btn" :disabled="!!busy||locked||!ysm?.currentModel" @click="useCurrentYsm">使用当前外观</button><button class="btn btn-primary" :disabled="!canYsm||dirty||!draft.id||!draft.appearance?.ysm" @click="applyYsm">{{busy==='ysmApply'?'正在切换…':'应用 YSM 外观'}}</button></div><small>{{running?'请先停止陪玩，再操作外观。':!connected?'在陪玩控制台连接 Numen 并选择同伴后，即可读取模型。':dirty?'保存角色卡后，即可将 YSM 外观应用到所选同伴。':'自动补齐后会请求 YSM 重载并确认换装。重载需要游戏权限；也可在游戏关闭时先准备模型。多人服务器还需在世界主机安装模型。'}}</small><p v-if="ysmMessage" class="ysm-receipt" role="status">{{ysmMessage}}</p></div>
          </div>
        </div>
      </div>
      <footer class="editor-footer"><div class="secondary-actions"><button class="text-btn" :disabled="!!busy||!draft.id" @click="duplicate">复制</button><button class="text-btn" :disabled="!!busy||dirty||!draft.id" @click="exportCard('json')">导出 JSON</button><button class="text-btn" :disabled="!!busy||dirty||!draft.id" @click="exportCard('md')">导出 Markdown</button><button class="text-btn danger" :disabled="!!busy||locked||!draft.id" @click="deleteOpen=true">删除</button></div><button class="btn btn-ghost" :disabled="!!busy||dirty||!draft.id||!canApply||running" @click="emit('apply',draft.id)">{{draft.id===currentId?'当前同伴正在使用此人设':'用于当前同伴的人设'}}</button></footer>
      <p v-if="locked" class="binding-note">当前同伴正在使用这张角色卡。停止陪玩后即可修改。</p>
    </div>
    <ConfirmModal :open="deleteOpen" title="删除角色卡？" message="角色卡及其同伴绑定将被移除，此操作无法撤销。" confirm-text="删除" :busy="busy==='delete'" :error="error" @confirm="remove" @cancel="deleteOpen=false"/>
    <ConfirmModal :open="discardOpen" title="放弃未保存的修改？" message="当前角色卡还有未保存的内容。" confirm-text="放弃修改" @confirm="discard" @cancel="discardOpen=false;pending=undefined"/>
  </section>
</template>
<style scoped>
.character-library{margin-top:22px;min-width:0;padding-bottom:16px}.library-toolbar,.library-title,.library-actions,.gallery-tools,.gallery-footer,.pagination,.editor-identity,.editor-footer,.secondary-actions,.skin-actions,.ysm-actions{display:flex;align-items:center;gap:12px}.library-toolbar{justify-content:space-between;margin-bottom:18px}.library-title{min-width:0}.library-toolbar h2{font-size:19px;margin:0;display:flex;align-items:center;gap:10px}.library-toolbar h2 small{font-size:11px;font-weight:500;border-radius:7px;padding:3px 7px;background:var(--accent-soft);color:var(--accent-2)}.library-toolbar p{font-size:12px;color:var(--text-dim);margin:6px 0 0}.back-button{width:34px;height:34px;border:1px solid var(--border);border-radius:10px;background:var(--card);color:var(--text);font-size:19px;cursor:pointer;flex:none}.btn{border:0;border-radius:9px;padding:10px 14px;font:inherit;font-size:12px;cursor:pointer;white-space:nowrap}.btn-primary{background:var(--accent);color:#fff}.btn-ghost{background:var(--card-2);border:1px solid var(--border);color:var(--text)}button:disabled{opacity:.45;cursor:not-allowed}.character-library input:not([type=checkbox]),.character-library textarea,.character-library select{box-sizing:border-box;width:100%;min-width:0;border:1px solid var(--border);border-radius:9px;background:var(--card-2);color:var(--text);font:inherit;font-size:12px;padding:10px 12px;outline:none}.character-library input:focus,.character-library textarea:focus,.character-library select:focus{border-color:var(--accent)}.gallery-tools{justify-content:space-between;margin-bottom:16px}.gallery-tools input{max-width:310px}.gallery-tools>span,.gallery-footer{font-size:11px;color:var(--text-dim)}.character-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:16px}.character-tile{border:1px solid var(--border);background:var(--surface-content);border-radius:16px;overflow:hidden;transition:border-color .18s,box-shadow .18s}.character-tile:hov